export const RANKS = [
  { id: "penjelajah", name: "Penjelajah", minXp: 0, icon: "🧭" },
  { id: "petualang", name: "Petualang", minXp: 1500, icon: "🎒" },
  { id: "jagoan", name: "Jagoan Kode", minXp: 3500, icon: "🏆" },
] as const;

export function rankForXp(xp: number) {
  let current: (typeof RANKS)[number] = RANKS[0];
  for (const r of RANKS) if (xp >= r.minXp) current = r;
  const next = RANKS.find((r) => r.minXp > xp) ?? null;
  return { current, next };
}

/* ------------------------------ Level unlocking ---------------------------- */

export const LEVEL_UNLOCK_RATIO = 0.7;

export type ProgressLike = {
  missionId: string;
  bestStars: number;
  completed: boolean;
  totalAttempts: number;
  totalFailed: number;
  totalHints: number;
  maxHintTierEver: number;
  noHintClear: boolean;
};

export type MissionLike = { id: string; level: number; order: number; concept: Concept };

export function starsNeededForNextLevel(missionsInLevel: number): number {
  return Math.ceil(missionsInLevel * 3 * LEVEL_UNLOCK_RATIO);
}

export type NodeStatus = "locked" | "open" | "completed";

export type LevelSummary = {
  level: number;
  concept: Concept;
  unlocked: boolean;
  stars: number;
  maxStars: number;
  starsToUnlockNext: number;
  missions: { id: string; status: NodeStatus; stars: number }[];
};

/**
 * FR-MISI-01 / FR-MISI-09: world map status. Level N+1 unlocks when ≥ 70% of
 * level N stars are collected. Inside a level, missions open one by one.
 */
export function buildMap(missions: MissionLike[], progress: ProgressLike[]): LevelSummary[] {
  const byId = new Map(progress.map((p) => [p.missionId, p]));
  const levels = [...new Set(missions.map((m) => m.level))].sort((a, b) => a - b);
  const result: LevelSummary[] = [];
  let prevUnlocked = true;
  let prevReached = true;
  for (const level of levels) {
    const ms = missions.filter((m) => m.level === level).sort((a, b) => a.order - b.order);
    const unlocked = prevUnlocked && prevReached;
    let previousDone = true;
    let stars = 0;
    const nodes = ms.map((m) => {
      const p = byId.get(m.id);
      const done = Boolean(p?.completed);
      const s = p?.bestStars ?? 0;
      stars += s;
      const status: NodeStatus = !unlocked ? "locked" : done ? "completed" : previousDone ? "open" : "locked";
      previousDone = done;
      return { id: m.id, status, stars: s };
    });
    const needed = starsNeededForNextLevel(ms.length);
    result.push({
      level,
      concept: ms[0]?.concept ?? "sequencing",
      unlocked,
      stars,
      maxStars: ms.length * 3,
      starsToUnlockNext: needed,
      missions: nodes,
    });
    prevUnlocked = unlocked;
    prevReached = stars >= needed;
  }
  return result;
}

/** Whether a given mission is playable for the child (server-side guard). */
export function isMissionPlayable(missionId: string, map: LevelSummary[]): boolean {
  for (const l of map) {
    const node = l.missions.find((m) => m.id === missionId);
    if (node) return node.status !== "locked";
  }
  return false;
}

