  "tanpa-petunjuk": { name: "Tanpa Petunjuk", icon: "🧠", desc: "Menyelesaikan 3 misi tanpa bantuan Bibi." },
  "bintang-tiga": { name: "Bintang Tiga", icon: "🌟", desc: "Mendapat 3 bintang pertama kali." },
  "master-sequencing": { name: "Master Urutan", icon: "🧩", desc: "Menyelesaikan semua misi Level 1." },
  "master-looping": { name: "Master Looping", icon: "🔁", desc: "Menyelesaikan semua misi Level 2." },
  "master-kondisional": { name: "Master Kondisional", icon: "🔀", desc: "Menyelesaikan semua misi Level 3." },
  "sahabat-bibi": { name: "Sahabat Bibi", icon: "💬", desc: "Bertanya kepada Bibi untuk pertama kali." },
} as const;

export type BadgeCode = keyof typeof BADGES;

export function evaluateBadges(
  missions: MissionLike[],
  progress: ProgressLike[],
  opts: { askedBibi: boolean },
): BadgeCode[] {
  const earned: BadgeCode[] = [];
  const done = progress.filter((p) => p.completed);
  if (done.length >= 1) earned.push("misi-pertama");
  if (done.filter((p) => p.noHintClear).length >= 3) earned.push("tanpa-petunjuk");
  if (done.some((p) => p.bestStars >= 3)) earned.push("bintang-tiga");
  const levelDone = (level: number) => {
    const ids = missions.filter((m) => m.level === level).map((m) => m.id);
    return ids.length > 0 && ids.every((id) => done.some((p) => p.missionId === id));
  };
  if (levelDone(1)) earned.push("master-sequencing");
  if (levelDone(2)) earned.push("master-looping");
  if (levelDone(3)) earned.push("master-kondisional");
  if (opts.askedBibi) earned.push("sahabat-bibi");
  return earned;
}

/* ---------------------------- Concept mastery ------------------------------ */

export type Mastery = "sudah-paham" | "sedang-belajar" | "perlu-bantuan" | "belum-mulai";

export const MASTERY_LABEL: Record<Mastery, string> = {
  "sudah-paham": "Sudah Paham",
  "sedang-belajar": "Sedang Belajar",
  "perlu-bantuan": "Perlu Bantuan",
  "belum-mulai": "Belum Mulai",
};

/** FR-DASH-03: simple, plain-language mastery indicator per concept. */
export function conceptMastery(missions: MissionLike[], progress: ProgressLike[], concept: Concept): Mastery {
  const ids = new Set(missions.filter((m) => m.concept === concept).map((m) => m.id));
  const ps = progress.filter((p) => ids.has(p.missionId));
  const attempts = ps.reduce((a, p) => a + p.totalAttempts, 0);
  if (attempts === 0) return "belum-mulai";
  const completed = ps.filter((p) => p.completed);
  const stars = completed.reduce((a, p) => a + p.bestStars, 0);
  const failed = ps.reduce((a, p) => a + p.totalFailed, 0);
  const maxStars = ids.size * 3;
  const failRate = failed / Math.max(1, attempts);
  if (completed.length === ids.size && stars >= Math.ceil(maxStars * LEVEL_UNLOCK_RATIO)) return "sudah-paham";
  const struggling = ps.some((p) => !p.completed && p.totalFailed >= 5) || (failRate > 0.75 && attempts >= 6);
  if (struggling) return "perlu-bantuan";
  return "sedang-belajar";
}

