import { z } from "zod";
import type { Block, ClientMission, Mission } from "@/lib/engine/types";
import level1 from "@/content/missions/level-1.json";
import level2 from "@/content/missions/level-2.json";
import level3 from "@/content/missions/level-3.json";

/* ------------------------------- Zod schemas ------------------------------- */

export const blockSchema: z.ZodType<Block> = z.lazy(() =>
  z.discriminatedUnion("kind", [
    z.object({ id: z.string().min(1).max(40), kind: z.literal("action"), action: z.string().min(1).max(40) }),
    z.object({
      id: z.string().min(1).max(40),
      kind: z.literal("repeat"),
      times: z.number().int(),
      body: z.array(blockSchema).max(30),
    }),
    z.object({
      id: z.string().min(1).max(40),
      kind: z.literal("if"),
      cond: z.string().max(40),
      then: z.array(blockSchema).max(30),
      else: z.array(blockSchema).max(30),
    }),
  ]),
);

export const programSchema = z.array(blockSchema).max(30);

const direction = z.enum(["N", "E", "S", "W"]);

const worldSchema = z.discriminatedUnion("type", [
  z.object({
    type: z.literal("grid"),
    width: z.number().int().min(1).max(10),
    height: z.number().int().min(1).max(10),
    start: z.object({ x: z.number().int(), y: z.number().int(), dir: direction }),
    hero: z.string(),
    layouts: z.array(z.array(z.string())).min(1),
    legend: z.record(z.string(), z.string()).optional(),
    goal: z.object({
      reach: z.boolean().optional(),
      collectAll: z.boolean().optional(),
      waterAll: z.boolean().optional(),
      pickAll: z.boolean().optional(),
    }),
  }),
  z.object({
    type: z.literal("numberline"),
    start: z.number(),
    target: z.number(),
    min: z.number(),
    max: z.number(),
    hero: z.string(),
    marks: z.array(z.number()).optional(),
  }),
  z.object({
    type: z.literal("sort"),
    items: z.array(
      z.object({
        label: z.string(),
        emoji: z.string().optional(),
        props: z.record(z.string(), z.boolean()),
        answer: z.string(),
      }),
    ),
    bins: z.array(z.object({ id: z.string(), label: z.string(), emoji: z.string() })).min(2),
  }),
  z.object({
    type: z.literal("sequence"),
    cards: z.array(z.object({ id: z.string(), label: z.string(), emoji: z.string() })),
    answer: z.array(z.string()).min(2),
  }),
]);

export const missionSchema = z.object({
  id: z.string().regex(/^L\d-M\d+$/),
  level: z.union([z.literal(1), z.literal(2), z.literal(3)]),
  order: z.number().int().min(1),
  title: z.string().min(3),
  subject: z.enum(["IPA", "Matematika"]),
  concept: z.enum(["sequencing", "looping", "conditional"]),
  story: z.string().min(10),
  goal: z.string().min(5),
  world: worldSchema,
  palette: z.object({
    actions: z.array(z.object({ action: z.string(), label: z.string(), icon: z.string() })).min(1),
    repeat: z.boolean().optional(),
    ifElse: z.boolean().optional(),
    conditions: z.array(z.object({ id: z.string(), label: z.string() })).optional(),
  }),
  optimalBlocks: z.number().int().min(1),
  hints: z.object({
    tier1: z.array(z.string()).min(1),
    tier2: z.array(z.string()).min(1),
    tier3: z.array(z.string()).min(1),
  }),
  solution: programSchema,
});

/* --------------------------------- Loader ---------------------------------- */

const ALL: Mission[] = [...level1, ...level2, ...level3]
  .map((m) => missionSchema.parse(m) as Mission)
  .sort((a, b) => a.level - b.level || a.order - b.order);

export function getAllMissions(): Mission[] {
  return ALL;
}

export function getMission(id: string): Mission | undefined {
  return ALL.find((m) => m.id === id);
}

export function getMissionsByLevel(level: number): Mission[] {
  return ALL.filter((m) => m.level === level);
}

/** Strip server-only data (hints and canonical solution) before sending to a browser. */
export function toClientMission(m: Mission): ClientMission {
  // eslint-disable-next-line @typescript-eslint/no-unused-vars
  const { hints, solution, ...rest } = m;
  return rest;
}

export function nextMissionId(id: string): string | null {
  const i = ALL.findIndex((m) => m.id === id);
  return i >= 0 && i + 1 < ALL.length ? ALL[i + 1].id : null;
}

export const LEVEL_INFO = {
  1: { name: "Level 1: Urutan", concept: "sequencing", icon: "🧩", color: "#4CB5F5", blurb: "Susun langkah dengan urutan yang benar." },
  2: { name: "Level 2: Perulangan", concept: "looping", icon: "🔁", color: "#7BC74D", blurb: "Ulangi gerakan yang sama dengan pintar." },
