import type { Block, Mission, Palette } from "@/lib/engine/types";

/**
 * Server-side guardrails for "Tanya Bibi AI" (FR-AI-S1..S4).
 * These are deliberately conservative: when in doubt, Bibi redirects gently
 * back to the mission instead of answering.
 */

export const MAX_INPUT_CHARS = 280;

export const FALLBACK_MESSAGE = "Bibi lagi istirahat sebentar, coba lagi ya! ☕";
export const INJECTION_REPLY =
  "Hihi, Bibi tetap Bibi, ya! 😊 Bibi di sini untuk menemanimu menyelesaikan misi. Yuk, lihat lagi blok-blokmu!";
export const UNSAFE_REPLY =
  "Yuk, kita pakai kata-kata yang baik ya. 🌈 Bibi siap bantu misimu kalau kamu mau!";
export const WELLBEING_REPLY =
  "Bibi dengar kamu sedang merasa tidak nyaman. 💛 Ceritakan ke orang tua, guru, atau orang dewasa yang kamu percaya, ya. Mereka sayang kamu.";
export const LEAK_REPLY =
  "Ups, Bibi hampir membocorkan jawabannya! 🙊 Coba pikirkan lagi langkah pertama, kamu pasti bisa.";
export const OFFTOPIC_REPLY =
  "Pertanyaan yang seru! Tapi sekarang kita fokus ke misi dulu, ya. 🚀 Mau Bibi bantu bagian mana?";

/* -------------------------------- Normalize -------------------------------- */

export function normalize(text: string): string {
  return text
    .toLowerCase()
    .normalize("NFKC")
    .replace(/[\u2018\u2019\u201C\u201D]/g, '"')
    .replace(/\s+/g, " ")
    .trim();
}

/* ----------------------------------- PII ----------------------------------- */

const PII_PATTERNS: { re: RegExp; label: string }[] = [
  { re: /[\w.+-]+@[\w-]+\.[\w.-]+/gi, label: "[email disamarkan]" },
  { re: /(?:\+62|62|0)8\d[\d\s-]{6,12}\d/g, label: "[nomor disamarkan]" },
  { re: /\b\d{9,}\b/g, label: "[nomor disamarkan]" },
  {
    re: /\b(?:jalan|jln\.?|jl\.?|gang|gg\.?|komplek|perumahan|perum\.?)\s+[\w.'-]+(?:\s+(?:no\.?|nomor)?\s*[\w./-]+){0,4}/gi,
    label: "[alamat disamarkan]",
  },
  { re: /\brt\s*\.?\s*\d+\s*\/?\s*rw\s*\.?\s*\d+/gi, label: "[alamat disamarkan]" },
  {
    re: /\b(?:sd|sdn|sdit|mi|min|sekolah dasar)\s+(?:negeri\s+|swasta\s+|islam\s+|kristen\s+|katolik\s+)?[\w.'-]+(?:\s+[\w.'-]+){0,2}/gi,
    label: "[sekolah disamarkan]",
  },
  {
    re: /\b(nama(?:ku| aku| saya)?(?: adalah)?|aku bernama|saya bernama)\s+[a-z][\w'-]*(?:\s+[a-z][\w'-]*){1,3}/gi,
    label: "$1 [nama disamarkan]",
  },
  { re: /https?:\/\/\S+|www\.\S+/gi, label: "[tautan disamarkan]" },
];

/** FR-AI-S4: mask personal data before it is sent to the model or stored. */
export function maskPII(text: string): { text: string; masked: boolean } {
  let out = text;
  for (const { re, label } of PII_PATTERNS) out = out.replace(re, label);
  return { text: out, masked: out !== text };
}

/* ------------------------------ Classification ----------------------------- */

const INJECTION_PATTERNS = [
  /abaikan\s+(semua\s+|seluruh\s+)?(instruksi|perintah|aturan|arahan)/,
  /lupakan\s+(semua\s+)?(instruksi|perintah|aturan)/,
  /ignore\s+(all\s+|any\s+|the\s+)?(previous|prior|above)?\s*(instructions|rules|prompts?)/,
  /system\s*prompt|prompt\s*sistem|instruksi\s*sistem/,
  /(kamu|anda)\s+(sekarang|mulai sekarang)\s+(adalah|jadi|menjadi)/,
  /pura[- ]?pura\s+(jadi|menjadi)/,
  /\b(jailbreak|dan mode|developer mode|mode pengembang|roleplay)\b/,
  /you\s+are\s+now|act\s+as|pretend\s+to\s+be/,
];

const ANSWER_REQUEST_PATTERNS = [
  /(kasih|beri|berikan|kasi|tunjukkan|sebutkan|tulis(kan)?)\s+(aku\s+|saya\s+)?(jawaban|solusi|kunci|susunan|urutan blok|program)(nya)?/,
  /(jawaban|solusi|kunci jawaban)(nya)?\s+(apa|dong|lengkap|langsung)/,
  /apa\s+(jawaban|solusi)(nya)?/,
  /(susunan|urutan)\s+blok(nya)?\s+(yang\s+)?(benar|lengkap)/,
  /(kerjakan|selesaikan)\s+(misi|soal)(nya)?\s+(untuk|buat)\s*(ku|aku|saya)/,
];

const PROFANITY = [
  "bangsat", "bajingan", "goblok", "tolol", "kontol", "memek", "ngentot", "kampret", "brengsek",
  "tai", "setan lu", "babi lu", "fuck", "shit", "bitch", "asshole", "dick",
];
const ADULT_TOPICS = [
  "porno", "porn", "seks", "sex", "bugil", "telanjang", "narkoba", "ganja", "sabu", "judi", "slot online",
  "rokok", "vape", "miras", "mabuk", "senjata api", "pistol", "bom", "pacaran",
];
const WELLBEING = [
  "bunuh diri", "ingin mati", "pengen mati", "mau mati", "menyakiti diri", "dipukul", "dibully", "di-bully",
  "dirundung", "disakiti",
];

function containsWord(text: string, words: string[]): boolean {
  return words.some((w) => new RegExp(`(^|[^a-z])${w.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}($|[^a-z])`).test(text));
}

export type InputVerdict =
  | { kind: "ok"; answerRequest: boolean }
  | { kind: "injection" }
  | { kind: "unsafe" }
  | { kind: "wellbeing" }
  | { kind: "empty" };

/** FR-AI-S2 / S3: server-side input filter. */
export function classifyInput(raw: string): InputVerdict {
  const t = normalize(raw);
  if (!t) return { kind: "empty" };
  if (containsWord(t, WELLBEING)) return { kind: "wellbeing" };
  if (containsWord(t, PROFANITY) || containsWord(t, ADULT_TOPICS)) return { kind: "unsafe" };
  if (INJECTION_PATTERNS.some((re) => re.test(t))) return { kind: "injection" };
  return { kind: "ok", answerRequest: ANSWER_REQUEST_PATTERNS.some((re) => re.test(t)) };
}

/* ---------------------------- Solution leakage ----------------------------- */

const esc = (s: string) => s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");

function actionLabel(palette: Palette, action: string) {
  const label = palette.actions.find((a) => a.action === action)?.label ?? action;
  return normalize(label).replace(/^ke\s+/, "");
}
function condLabel(palette: Palette, cond: string) {
  return normalize(palette.conditions?.find((c) => c.id === cond)?.label ?? cond);
}

type Token = { re: string; weight: number };

function tokensFor(blocks: Block[], palette: Palette): Token[] {
  const out: Token[] = [];
  let i = 0;
  while (i < blocks.length) {
    const b = blocks[i];
    if (b.kind === "action") {
      let count = 1;
      while (
        i + count < blocks.length &&
        blocks[i + count].kind === "action" &&
        (blocks[i + count] as typeof b).action === b.action
      ) {
        count++;
      }
      const l = esc(actionLabel(palette, b.action));
      const re =
        count === 1
          ? l
          : `(?:${l}(?:[\\s\\S]{0,40}?${l}){${count - 1}}|${l}\\W{0,12}(?:sebanyak\\s*)?${count}\\s*(?:x|kali))`;
      out.push({ re, weight: count });
      i += count;
      continue;
    }
    if (b.kind === "repeat") {
      out.push({ re: `(?:ulangi|ulang|diulang)\\W{0,12}(?:sebanyak\\s*)?${b.times}`, weight: 1 });
      out.push(...tokensFor(b.body, palette));
    } else {
      out.push({ re: `(?:jika|kalau|if)\\W{0,12}${esc(condLabel(palette, b.cond))}`, weight: 1 });
      out.push(...tokensFor(b.then, palette));
      if (b.else.length) {
        out.push({ re: "(?:lainnya|kalau tidak|jika tidak|else)", weight: 0 });
        out.push(...tokensFor(b.else, palette));
      }
    }
    i++;
  }
  return out;
}

/**
 * FR-AI-03: detect whether a text spells out the complete solution
 * (all solution blocks, in order). Partial hints are allowed.
 */
export function leaksSolution(text: string, mission: Pick<Mission, "solution" | "palette">): boolean {
  const tokens = tokensFor(mission.solution, mission.palette);
  const weight = tokens.reduce((a, t) => a + t.weight, 0);
  if (weight < 2) return false;
  const pattern = new RegExp(tokens.map((t) => t.re).join("[\\s\\S]{0,120}?"));
  return pattern.test(normalize(text));
}

/** FR-AI-S2: output filter applied to every sentence before it reaches the child. */
export function checkOutput(
  text: string,
  mission: Pick<Mission, "solution" | "palette">,
): { ok: true; text: string } | { ok: false; reason: "unsafe" | "leak" } {
  const t = normalize(text);
  if (containsWord(t, PROFANITY) || containsWord(t, ADULT_TOPICS)) return { ok: false, reason: "unsafe" };
  if (leaksSolution(text, mission)) return { ok: false, reason: "leak" };
  return { ok: true, text: maskPII(text).text };
}

/** Split streamed text into complete sentences, returning the unfinished rest. */
export function splitSentences(buffer: string): { sentences: string[]; rest: string } {
  const sentences: string[] = [];
  const re = /[^.!?\n]*[.!?\n]+(?:\s*\p{Extended_Pictographic}[\uFE0F\u200D\p{Extended_Pictographic}]*)*\s*/gu;
  let last = 0;
  let m: RegExpExecArray | null;
  while ((m = re.exec(buffer))) {
    if (m[0].length === 0) {
      re.lastIndex++;
      continue;
    }
    sentences.push(m[0]);
    last = m.index + m[0].length;
  }
  return { sentences, rest: buffer.slice(last) };
}

